#!/usr/bin/env bash
# B1: check the render toolchain and make fake media, so B can work with no keys.
#   1. ffmpeg >= 5 with libass + freetype and every filter render uses
#   2. fonts/NotoSans-Bold.ttf present, with Greek letters
#   3. runs/fake/rough_take.mp4: a 60 s stand-in take at an awkward size/fps (1366x768@25,
#      44.1 kHz stereo) to test fitting before C's real take lands in samples/
#   4. fixtures/run/ media regenerated by fixtures/make_media.sh (only with --fixtures)
set -euo pipefail
cd "$(dirname "$0")/.."

fail() { echo "FAIL: $*" >&2; exit 1; }
ok() { echo "ok: $*"; }

# --- 1. ffmpeg ----------------------------------------------------------------------
command -v ffmpeg >/dev/null || fail "ffmpeg not found"
command -v ffprobe >/dev/null || fail "ffprobe not found"
ver="$(ffmpeg -version | head -1 | sed -E 's/^ffmpeg version n?([0-9]+).*/\1/')"
[[ "$ver" =~ ^[0-9]+$ ]] && (( ver >= 5 )) || fail "need ffmpeg 5+, got: $(ffmpeg -version | head -1)"
ok "ffmpeg $ver"

FILTERS="$(ffmpeg -hide_banner -filters 2>/dev/null)"
for f in ass subtitles drawtext sidechaincompress amix tpad zoompan apad concat; do
  grep -q " $f " <<<"$FILTERS" || fail "ffmpeg filter '$f' missing (need a build with libass and freetype)"
done
ok "filters: ass subtitles drawtext sidechaincompress amix tpad zoompan apad concat"

# --- 2. font ------------------------------------------------------------------------
FONT=fonts/NotoSans-Bold.ttf
[[ -s $FONT ]] || fail "$FONT missing: copy NotoSans-Bold.ttf from fonts.google.com/noto into fonts/"
if command -v fc-query >/dev/null; then
  # U+03A9 (Greek capital omega) must be in the charset, or Greek captions render as boxes
  fc-query -f '%{charset}\n' "$FONT" | tr ' ' '\n' | awk -F- '
    { lo = strtonum("0x" $1); hi = ($2 == "") ? lo : strtonum("0x" $2) }
    lo <= 0x3A9 && 0x3A9 <= hi { found = 1 } END { exit !found }' ||
    fail "$FONT has no Greek letters"
  ok "$FONT (has Greek)"
else
  ok "$FONT (fc-query not installed, Greek not checked)"
fi

# Burn one Greek + Latin caption with the repo font: proves libass finds fonts/.
TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
printf '1\n00:00:00,000 --> 00:00:01,000\nDemoCut · Καλησπέρα\n' >"$TMP/t.srt"
ffmpeg -hide_banner -loglevel error -y -f lavfi -i color=c=black:s=320x180:d=1 \
  -vf "subtitles=$TMP/t.srt:fontsdir=fonts:force_style='FontName=Noto Sans,Bold=1'" \
  -frames:v 1 "$TMP/t.png" || fail "libass could not burn a caption with fonts/"
ok "libass burns captions with fonts/"

# --- 3. stand-in take ---------------------------------------------------------------
mkdir -p runs/fake
TAKE=runs/fake/rough_take.mp4
if [[ ! -s $TAKE ]]; then
  ffmpeg -hide_banner -loglevel error -y \
    -f lavfi -i "testsrc2=s=1366x768:r=25:d=60" \
    -f lavfi -i "sine=frequency=300:sample_rate=44100:duration=60" \
    -vf "drawtext=fontfile=$FONT:text='rough take  %{pts\:hms}':fontsize=48:fontcolor=white:box=1:boxcolor=black@0.5:x=40:y=40" \
    -c:v libx264 -preset veryfast -crf 30 -pix_fmt yuv420p -c:a aac -b:a 64k -ac 2 -shortest "$TAKE"
fi
ok "$TAKE ($(ffprobe -v error -select_streams v:0 -show_entries stream=width,height,r_frame_rate -of csv=p=0 "$TAKE"), $(ffprobe -v error -show_entries format=duration -of csv=p=0 "$TAKE") s)"

# --- 4. fixtures (shared: only regenerate on purpose) -------------------------------
if [[ "${1:-}" == "--fixtures" ]]; then
  bash fixtures/make_media.sh
  ok "fixtures/run media regenerated (check git diff before committing)"
fi

echo "B1 setup OK"
